def classify(sample, data):
    best = None
    best_d = None
    for feats, label in data:
        d = sum((a - b) ** 2 for a, b in zip(sample, feats))
        if best_d is None or d < best_d:
            best_d = d
            best = label
    return best

def is_spam(text, keywords, threshold):
    count = 0
    for w in text.split():
        w = w.strip('.,!?').lower()
        if w in keywords:
            count += 1
    return count >= threshold
